global _start

section .text
_start:
        jmp short call_shc

decoder:
        pop rsi                     

        ; register temizligi
        xor rax, rax
        xor rbx, rbx
        xor rdi, rdi
        xor rdx, rdx
        xor rcx, rcx

        mov bl, 0x4                ; baslangic anahtari
        mov dil, 7                  ; ilk indis
        
        mov dx, 724                 ; dongu siniri
        mov cx, 724                 ; dongu sayaci

decode_loop:
        xor rax, rax
        mov al, byte [rsi + rdi]    ; sifreli byte al de

        xor al, bl                  ; xor ile coz

        mov byte [rsi + rdi], al    ; cozulmus byte i ayni indise yaz

        ; dinamik key = key + plaintext
        lea ebx, [rbx + rax] 
        movzx ebx, bl  ; sadece alttaki 8 bit
        ; encoderdaki &0xFF mantigi             

        inc rdi                     ; sonraki indis

        ; indis sona geldi mi?
        cmp di, dx
        jne continue_loop
        xor rdi, rdi                ; eger sona geldiysek basa don 

continue_loop:
        loop decode_loop        

        ; cozme bitti 
        jmp rsi                     

call_shc:
        call decoder

